import React from 'react'

function page() {
    return (
        <div>
            {wishlistItems.map((item) => (
                <div key={item.id} className="...">
                    <img src={item.image} alt={item.name} className="w-40 h-40 object-cover" />
                    <p>{item.name}</p>
                    <p>Rs. {item.price}</p>
                    <button onClick={() => removeItem(item.id)}>Remove</button>
                </div>
            ))}</div>
    )
}

export default page
